create function public.validate_substitute() returns trigger language plpgsql security invoker set search_path='' as $$ declare m public.matches%rowtype; p public.players%rowtype; cap int; begin select * into m from public.matches where id=new.match_id for update; select * into p from public.players where id=new.player_id for update; select max_subs into cap from public.tournaments where id=new.tournament_id; if m.id is null or p.id is null or m.official or p.team_id is not null or new.team_id is distinct from m.home_id and new.team_id is distinct from m.away_id then raise exception 'Suplencia inválida'; end if; if (select count(*) from public.substitutes s where s.match_id=new.match_id and s.team_id=new.team_id and (tg_op='INSERT' or s.player_id<>old.player_id))>=cap then raise exception 'Límite de suplentes alcanzado'; end if; return new; end $$;
create trigger validate_substitute before insert or update on public.substitutes for each row execute function public.validate_substitute();
alter table public.matches add constraint group_requires_opponent check(stage<>'group' or away_id is not null);
alter table public.matches add constraint knockout_tie_requires_penalties check(stage<>'knockout' or not official or home_score<>away_score or (home_penalties is not null and away_penalties is not null and home_penalties<>away_penalties));
create unique index unique_group_pair on public.matches(tournament_id,least(home_id,away_id),greatest(home_id,away_id)) where stage='group';
